def 현재선택영역_글자수():
    hwp.InitScan(option=None, Range=0xff, spara=None, spos=None, epara=None, epos=None)
    try:
        _, text = hwp.GetText()
        return len(text)
    finally:
        hwp.ReleaseScan()

def 현재선택영역_텍스트():
    try:
        hwp.InitScan(option=None, Range=0xff, spara=None, spos=None, epara=None, epos=None)
        try:
            _, text = hwp.GetText()
            return text or ""
        finally:
            hwp.ReleaseScan()
    except Exception:
        return ""

