def 색_rgb(hex색):
    return tuple(int(hex색[i:i + 2], 16) for i in (1, 3, 5))



def 고양이_표시용_배경투명화(image):
    """원본을 보존하고 표시용 복사본의 외곽 흰 배경만 투명화한다.

    테두리와 연결된 거의 흰 픽셀만 탐색하므로 검은 외곽선 안의 흰 눈은
    유지된다. 축소 전에 실행하여 흰 사각형과 축소 시의 흰 테두리를 막는다.
    """
    img = image.convert("RGBA").copy()
    width, height = img.size
    pixels = img.load()
    visited = bytearray(width * height)
    background = bytearray(width * height)
    pending = deque()

    def visit(x, y):
        index = y * width + x
        if visited[index]:
            return
        visited[index] = 1
        r, g, b, a = pixels[x, y]
        if a == 0 or (min(r, g, b) >= 235 and max(r, g, b) - min(r, g, b) <= 20):
            background[index] = 1
            pending.append((x, y))

    for x in range(width):
        visit(x, 0)
        visit(x, height - 1)
    for y in range(height):
        visit(0, y)
        visit(width - 1, y)
    while pending:
        x, y = pending.popleft()
        if x: visit(x - 1, y)
        if x + 1 < width: visit(x + 1, y)
        if y: visit(x, y - 1)
        if y + 1 < height: visit(x, y + 1)

    for y in range(height):
        for x in range(width):
            index = y * width + x
            r, g, b, a = pixels[x, y]
            if background[index]:
                pixels[x, y] = (r, g, b, 0)
            elif a and max(r, g, b) - min(r, g, b) <= 20 and min(r, g, b) >= 64:
                # 흰 배경에 섞인 검정 선 가장자리의 회색만 반투명 검정으로.
                adjacent = ((x > 0 and background[index - 1]) or
                            (x + 1 < width and background[index + 1]) or
                            (y > 0 and background[index - width]) or
                            (y + 1 < height and background[index + width]))
                if adjacent:
                    pixels[x, y] = (0, 0, 0, round(a * (255 - min(r, g, b)) / 255))
    return img


class LiveStageBoard(tk.Canvas):
    """실제 단계 이벤트를 표시. 점멸은 실행 표시이며 완료율 추정이 아니다."""
    def __init__(self, parent, animated):
        super().__init__(parent, height=50, bg=UI_COLORS['bg'], highlightthickness=0)
        self.animated = animated
        self.active = None
        self.visited = set()
        self.started = time.monotonic()
        self.last_signal = self.started
        self.detail = '작업 대기'
        self.outcome = None
        self.ended = None
        self.result_message = None   # 작업이 모두 끝났을 때 보여 줄 메시지(예: 절약된 시간)
        self.job = None
        self.bind('<Destroy>', self._destroy, add='+')
        self._frame()

    def reset(self):
        self.active = None
        self.visited.clear()
        self.outcome = None
        self.ended = None
        self.result_message = None
        self.detail = '문서 처리 준비'
        self.signal()
        self.draw()

    def signal(self, detail=None):
        self.last_signal = time.monotonic()
        if detail is not None:
            self.detail = str(detail)

    def activate(self, stage):
        if stage not in 진행단계_순서:
            return
        if stage != self.active:
            if self.active:
                self.visited.add(self.active)
            self.active = stage
            self.started = time.monotonic()
        self.outcome = None
        self.ended = None
        self.signal()
        self.draw()

    def set_result_message(self, message):
        self.result_message = message
        self.draw()

    def finish(self, outcome):
        self.outcome = outcome
        self.ended = time.monotonic()
        self.signal()
        self.draw()

    def _destroy(self, event):
        if event.widget is self and self.job is not None:
            self.after_cancel(self.job)
            self.job = None

    def _frame(self):
        self.job = None
        if self.winfo_ismapped():
            self.draw()
        self.job = self.after(66 if self.winfo_ismapped() else 250, self._frame)

    def draw(self):
        self.delete('all')
        now = time.monotonic()
        width = max(1, self.winfo_width())
        for i, stage in enumerate(진행단계_순서):
            left, right = i*width/6+2, (i+1)*width/6-2
            current = self.active == stage
            busy = current and self.outcome is None
            # 처리한 단계는 진한 색 바탕 + 흰 글씨로 표시한다(아직 처리 전 단계만 연한 색).
            # 색은 모두 앱 테마 청록(UI_COLORS['teal'])에서 이어 받는다.
            #   처리한 칸 = 테마 청록 / 완료 = 진한 청록 / 진행 중 = 진한 청록↔더 진한 청록 깜빡임
            fill, prefix, text_color = '#f0ece8', '', UI_COLORS['ink']
            if stage in self.visited:
                fill, prefix, text_color = UI_COLORS['teal'], '· ', 'white'
            if current:
                text_color = 'white'
                if self.outcome:
                    fill = '#B85A22' if self.outcome != '완료' else UI_COLORS['teal_dark']
                    prefix = '✓ ' if self.outcome == '완료' else '■ '
                else:
                    mix = .5 + .5*math.sin(now*3) if self.animated.get() else .5
                    low = 색_rgb(UI_COLORS['teal_dark'])
                    high = tuple(round(v*0.72) for v in low)
                    fill = '#'+''.join(f'{round(a+(b-a)*mix):02x}' for a,b in zip(low, high))
            self.create_rectangle(left,2,right,27,fill=fill,outline='')
            self.create_text((left+right)/2+6,14,text=prefix+stage,fill=text_color,font=('맑은 고딕',8,'bold' if current else 'normal'))
            if busy:
                angle = (now*230)%360 if self.animated.get() else 90
                self.create_arc(left+5,8,left+16,19,start=angle,extent=265,style='arc',outline='white',width=2)
        if self.active:
            elapsed = int((self.ended or now)-self.started)
            silent = int(now-self.last_signal)
            message = f'{self.active} · {self.outcome or "실행 중"} · {elapsed}초'
            if self.outcome is None and silent >= 15:
                message += f'   |   한글 응답 대기 {silent}초 · 중단은 현재 호출 반환 후 적용'
            elif self.outcome is None:
                message += f'   |   마지막 처리 신호 {silent}초 전'
        else:
            message = self.outcome or ''
        font = ('맑은 고딕',8)
        if self.outcome == '완료' and self.result_message:
            message, font = self.result_message, ('맑은 고딕',9,'bold')
        self.create_text(5,39,anchor='w',text=message,fill=UI_COLORS['teal_dark'],font=font)


# 상단(실행창 오른쪽 위)의 고양이 캐릭터.
# 앱 상태(환영/설정/자간정리/서식정리/완료 등)에
# 맞춰 한 마리만 반응하는 v1.50까지의 모습을 그대로 유지한다.
class CatCompanion(tk.Canvas):
    """사용자가 선택한 이미지에 이동/점프/글자 정렬 연출을 더한다.

    원본 이미지는 수정하지 않는다. Tk 메인 스레드의 after만 사용하며
    창이 숨겨지면 다시 그리지 않고, 파괴 시 예약 콜백을 취소한다.
    """
    def __init__(self, parent, animated, **kwargs):
        super().__init__(parent, width=136, height=76, bg=UI_COLORS["bg"],
                         highlightthickness=0, **kwargs)
        self.animated = animated
        self.photo = None
        self.photos = {}
        self.state_name = "welcome"
        self.tick = 0
        self.job = None
        self.bind("<Destroy>", self._destroy, add="+")
        self._frame()

    def set_image(self, photo):
        self.photos = photo if isinstance(photo, dict) else {}
        self.photo = photo.get("welcome") if isinstance(photo, dict) else photo
        self.tick = 0
        self.draw()

    def set_frames(self, frames):
        # 캐릭터 공통 인터페이스 호환을 위해,
        # 프레임 목록 자체는 쓰지 않지만 호출은 조용히 받아들인다.
        pass

    def set_state(self, name):
        self.state_name = name
        self.tick = 0
        self.draw()

    def _destroy(self, event):
        if event.widget is self and self.job is not None:
            try:
                self.after_cancel(self.job)
            except tk.TclError:
                pass
            self.job = None

    def _frame(self):
        self.job = None
        if self.winfo_ismapped() and self.animated.get():
            self.tick += 1
            self.draw()
        self.job = self.after(100, self._frame)

    def draw(self):
        self.delete("all")
        c = UI_COLORS
        motion = self.animated.get()
        t = self.tick if motion else 0
        if self.state_name in ("stopped", "error"):
            motion = False
        busy = self.state_name in ("spacing", "format", "all", "working")
        x = 72 + (math.sin(t / 5) * 9 if busy and motion else 0)
        y = 53 - (abs(math.sin(t / 4)) * (9 if self.state_name == "done" else 4) if motion else 0)
        self.create_oval(25, 94, 118, 105, fill=c["rose"], outline="")
        current_photo = self.photos.get(self.state_name, self.photo)
        if current_photo is not None:
            self.create_image(x, y, image=current_photo)
        else:
            self.create_oval(43, 46, 98, 88, fill=c["lavender"], outline="")
            for px, py in ((44, 34), (63, 25), (85, 28), (101, 42)):
                self.create_oval(px-8, py-8, px+8, py+8, fill=c["lavender"], outline="")
            self.create_text(74, 116, text="고양이 이미지를 선택해 주세요", font=("맑은 고딕", 8), fill=c["muted"])
        labels = {"welcome": "반가워요!", "settings": "취향대로 골라요", "spacing": "글자 사이를 쏙쏙",
                  "format": "가지런히 정리 중", "all": "차근차근 정리 중", "working": "함께 정리해요",
                  "done": "정리 끝! 수고했어요", "error": "기록을 확인해요", "stopped": "잠시 쉬어 가요"}
        self.create_text(165, 22, text=labels.get(self.state_name, "함께 정리해요"), width=110,
                         font=("맑은 고딕", 9, "bold"), fill=c["ink"])
        if self.state_name == "spacing":
            gap = 4 + (1 + math.sin(t / 5)) * 6 if motion else 9
            for i, char in enumerate("가나다"):
                self.create_text(145 + i * (13 + gap), 70, text=char, fill=c["teal"], font=("맑은 고딕", 10, "bold"))
        elif self.state_name in ("format", "all", "working"):
            for i in range(3):
                shift = math.sin(t / 5 + i) * 7 if motion else 0
                self.create_line(136 + shift, 55+i*15, 203, 55+i*15, fill=c["teal"], width=4)
        elif self.state_name == "done":
            for i in range(4):
                self.create_text(132+i*22, 65+math.sin(t/4+i)*10 if motion else 65,
                                 text="✦", fill=(c["orange"] if i%2 else c["lavender"]), font=("맑은 고딕", 15))
        else:
            self.create_text(165, 70, text="✦", fill=c["orange"], font=("맑은 고딕", 24))


# ============================================================
# GUI 클래스
# ============================================================
        self.scale('all', 0, 0, .6, .6)
        for item in self.find_all():
            if self.type(item) == 'text':
                self.itemconfigure(item, font=('맑은 고딕', 7), width=66)


