        cat_tab = tabs["cat"]
        ttk.Label(cat_tab, text="문서 정리를 함께할 고양이 친구", font=("맑은 고딕", 15, "bold")).pack(anchor="w")
        ttk.Label(cat_tab, text="상단 고양이 이미지를 선택할 수 있어요.\n세부설정에는 cat.png의 고양이를 정지 이미지로 표시합니다.",
                  wraplength=680, style="Hint.TLabel").pack(anchor="w", pady=10)
